parameters.jsCode:
const raw = $input.first().json.text ?? '';

let items;
try {
  items = JSON.parse(String(raw).replace(/```json\n?|```/g, '').trim());
} catch (e) {
  items = [];
}
if (!Array.isArray(items)) items = [];

const calendarItems = items.filter(i => i.category === 'calendar');

// Cycle 3 deliberately handles only the FIRST item in the calendar group.
// Cycle 5 handles every group.
const first = calendarItems[0];
if (!first) return [];

const date = first.due_date;

return [{
  json: {
    action: first.action,
    owner: first.owner,
    due_date: date,
    category: first.category,
    reason: first.reason,
    event_start: date ? date + 'T09:00:00+02:00' : null,
    event_end: date ? date + 'T09:30:00+02:00' : null,
    calendar_items_found: calendarItems.length,
    total_items_found: items.length
  }
}];

